// Newsprint-weight paper: warm stock, slow mottling, fine fibre, a lamp's falloff.
float h21(float2 p) { return frac(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
float vn(float2 p) {
  float2 i = floor(p), f = frac(p);
  float2 u = f * f * (3.0 - 2.0 * f);
  return lerp(lerp(h21(i), h21(i + float2(1, 0)), u.x), lerp(h21(i + float2(0, 1)), h21(i + float2(1, 1)), u.x), u.y);
}
float4 shade(float2 pos, float px) {
  float2 uv = pos / size();
  float3 base = from_srgb(float4(0.949, 0.929, 0.890, 1.0)).rgb;
  float mott = vn(pos / 180.0) * 0.6 + vn(pos / 61.0) * 0.4;
  float fib = vn(float2(pos.x / 1.6, pos.y / 9.0)) * 0.5 + vn(pos / 2.2) * 0.5;
  float3 c = base * (1.0 + (mott - 0.5) * 0.035 + (fib - 0.5) * 0.03);
  float r = length((uv - float2(0.5, 0.42)) * float2(0.9, 1.0));
  c *= 1.0 - smoothstep(0.35, 0.95, r) * 0.07;
  return float4(c, 1.0);
}

float4 shade(float2 pos, float px) {
  float2 p = floor(pos) + floor(time() * 24.0) * float2(37.0, 17.0);
  float h = frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
  float g = frac(sin(dot(p + 3.1, float2(39.346, 11.135))) * 24634.6345);
  return float4(float3((h + g) * 0.5), 1.0);
}
